-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "itIT" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.paladin.holy.Name"] = "Sacro"
L["rm.era.paladin.holy.Description"] = "Cure in gruppo con l'albero Sacro, dal livello 10. Agisce sul tuo bersaglio amico e sceglie la cura in base alla salute mancante: Purificazione o Depurazione, Folgore Sacra mentre ti muovi, Luce Sacra di grado massimo sotto il 40%, Luce Sacra di grado 6 sotto il 65%, Lampo di Luce di grado massimo sotto l'85%, Lampo di Luce di grado 4 sotto il 95%. Con un nemico a portata di mischia: Sigillo della Saggezza e, fuori dalle incursioni, Giudizio. Promemoria: Aura di Concentrazione o della Devozione, Benedizione della Saggezza, Favore Divino e Mano Celestiale per un bersaglio con pochissima salute. La scelta di chi curare resta a te; i Paladini Sacro che giocano da soli ricevono la rotazione integrata Castigo."
L["rm.era.paladin.protection.Name"] = "Protezione"
L["rm.era.paladin.protection.Description"] = "Ruolo da difensore dal livello 1 al 60, scelta con Giusta Furia o con l'albero Protezione. Sigillo della Rettitudine (Sigillo della Saggezza quando il mana scende sotto il 40%), Scudo Benedetto e Giudizio per ingaggiare, Scudo Benedetto sempre attivo, Consacrazione e Ira Sacra (Non Morti e Demoni) quando due o più nemici ti attaccano, altrimenti Giudizio del Crociato una volta, poi Giudizio e Consacrazione con mana in avanzo, Esorcismo su Non Morti e Demoni. Promemoria: Giusta Furia, Aura della Devozione, Santuario, Re o Vigore, Mano Celestiale quando sei quasi morto. Provocazioni, uso ripetuto di Benedizione dei Re e gradi degli incantesimi restano a te."
L["rm.era.paladin.protection.icyveins.Name"] = "Protezione, Sigillo della Saggezza (Icy Veins)"
L["rm.era.paladin.protection.icyveins.Description"] = "Il ruolo da difensore in incursione di Icy Veins con la rotazione della Saggezza di Wowhead, un'alternativa alla rotazione integrata consigliata Protezione, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Mantiene attivo Sigillo della Saggezza e lo giudica ogni volta che il bersaglio non ha Giudizio della Saggezza, altrimenti giudica solo per ingaggiare; Scudo Benedetto, Consacrazione a ogni tempo di recupero, Ira Sacra sui gruppi di Non Morti e Demoni, Esorcismo, e Benedizione Superiore dei Re come riempitivo per la minaccia in incursione. Stessi promemoria della rotazione integrata consigliata."
L["rm.era.paladin.retribution.Name"] = "Castigo"
L["rm.era.paladin.retribution.Description"] = "Castigo in mischia dal livello 1 al 60, e la scelta predefinita per qualsiasi Paladino a cui non si adatta nessun'altra rotazione integrata. Sulle élite e nei combattimenti lunghi fuori dalle incursioni attiva Sigillo del Crociato e lo giudica una volta; altrimenti mantiene attivo un sigillo (Comando con un'arma da 3,5 secondi o più lenta, altrimenti Rettitudine), Esorcismo e Ira Sacra su Non Morti e Demoni, Martello dell'Ira, Giudizio appena pronto, Consacrazione mentre Vendetta è attiva o contro due o più nemici vicini. Promemoria: Aura della Santità, del Castigo o della Devozione, Benedizione della Saggezza da solo o del Vigore in gruppo, una cura tra un combattimento e l'altro, Scudo Divino, Protezione Divina o Mano Celestiale quando stai per morire. L'alternanza dei sigilli è una rotazione integrata separata; scelta del bersaglio e posizionamento restano a te."
L["rm.era.paladin.retribution.twist.Name"] = "Castigo, alternanza dei sigilli"
L["rm.era.paladin.retribution.twist.Description"] = "Disattivata per impostazione predefinita; attivala se alterni i sigilli. Per un Paladino Castigo con Sigillo del Comando: mantiene attivo Sigillo della Rettitudine, passa a Sigillo del Comando di grado 1 negli ultimi 0,4 secondi prima di un colpo e poi torna indietro, Giudizio ogni volta che è pronto, Esorcismo e Ira Sacra su Non Morti e Demoni, Martello dell'Ira, Consacrazione con Vendetta. Richiede molto mana e un buon tempismo. Stessi promemoria della rotazione integrata Castigo."
L["rm.forever.paladin.holy.Name"] = "Sacro"
L["rm.forever.paladin.holy.Description"] = "Cure di gruppo una volta che Sacro è il tuo albero dei talenti principale con 21 punti (il livello di Folgore Sacra), mentre Giusta Furia è disattivata (anche uno \"Shockadin\" in gruppo finisce qui). Cura il tuo attuale bersaglio amico: Folgore Sacra su un bersaglio con la tua Veglia della Luce, Veglia della Luce in combattimento, Purificazione o Purifica, Folgore Sacra in movimento, Luce Sacra con Infusione di Luce, Lampo di Luce come cura principale. Su un nemico: Giudizio della Luce quando è attivo Sigillo della Luce, Folgore Sacra, Veglia della Luce, Colpo Sacro, Esorcismo. Promemoria: Sigillo della Luce quando non hai un sigillo, Favore Divino in combattimento su un bersaglio amico, la tua aura e Benedizione. Su Forever salute e mana sono nascosti agli addon, quindi il bersaglio che scegli è l'unico segno di chi ha bisogno di cure; Folgore Sacra d'emergenza, Luce Sacra per grandi carenze e Mano Celestiale sono una tua scelta."
L["rm.forever.paladin.holy.wowhead.Name"] = "Sacro, Folgore Sacra appena pronta (Wowhead)"
L["rm.forever.paladin.holy.wowhead.Description"] = "Lo stile di cura di Wowhead, un'alternativa alla rotazione integrata consigliata Sacro, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Folgore Sacra come cura abituale appena pronta, dissoluzioni, Lampo di Luce (su Forever la salute è nascosta, quindi Luce Sacra per grandi carenze spetta a te). Su un nemico mantiene il tuo Giudizio della Luce passando a Sigillo della Luce, giudicando e tornando a Sigillo della Rettitudine, poi Colpo Sacro, Esorcismo su Non Morti e Demoni, Folgore Sacra e Consacrazione. Stessi promemoria della rotazione integrata Sacro."
L["rm.forever.paladin.protection.Name"] = "Protezione (Wowhead)"
L["rm.forever.paladin.protection.Description"] = "Ruolo da difensore, una volta che Protezione è il tuo albero dei talenti principale o attivi Giusta Furia. Quando il bersaglio combatte qualcun altro: Giudizio con Sigillo della Furia (la provocazione), Giudizio Rapido per azzerarlo. Due o più nemici ingaggiati: Consacrazione, Esorcismo e Biasimo su Non Morti e Demoni, Colpo Sacro. Un solo nemico: Esorcismo su Non Morti e Demoni, Colpo Sacro, Consacrazione. Promemoria: Giusta Furia, Sigillo della Furia, Giudizio appena pronto, Scudo Sacro mentre fai da difensore, la tua aura e Benedizione. Su Forever salute e mana sono nascosti agli addon, quindi Baluardo del Templare e Mano Celestiale sono una tua scelta. Ingaggio, posizionamento e altre provocazioni restano a te."
L["rm.forever.paladin.protection.icyveins.Name"] = "Protezione, prima Consacrazione (Icy Veins)"
L["rm.forever.paladin.protection.icyveins.Description"] = "Lo stile da difensore di Icy Veins, un'alternativa alla rotazione integrata consigliata Protezione di Wowhead, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Prima Consacrazione ogni volta che te la puoi permettere, anche contro un solo nemico; Giudizio è riservato alle provocazioni (nessun promemoria appena pronto), con Giudizio Rapido per azzerarlo; poi Colpo Sacro ed Esorcismo su Non Morti e Demoni. Per il resto stessi promemoria da difensore."
L["rm.forever.paladin.retribution.Name"] = "Castigo"
L["rm.forever.paladin.retribution.Description"] = "Castigo e ogni Paladino in mischia dal livello 1 al 60, e la scelta predefinita del Paladino di Forever. Mantiene attivo un sigillo da danno, rinnovato solo quando sta per scadere: Sigillo del Crociato giudicato una volta su un bersaglio élite, poi Sigillo del Comando con un'arma lenta (3,0 s), altrimenti Sigillo della Rettitudine. Poi Colpo Sacro appena pronto, Folgore Sacra e Veglia della Luce per uno \"Shockadin\", Esorcismo su Non Morti e Demoni, Consacrazione contro tre o più nemici, Martello dell'Ira quando può essere lanciato, e mischia. Giudizio non attiva il tempo di recupero globale, quindi è un promemoria ogni volta che un sigillo è attivo. Altri promemoria: la tua aura e Benedizione (Aura del Castigo e Re una volta apprese; quelle che hai scelto vengono mantenute). Passo facoltativo, disattivato per impostazione predefinita: Martello della Giustizia prima di un Giudizio del Sigillo del Comando. Su Forever mana, salute e timer degli attacchi sono nascosti agli addon, quindi risparmiare mana, curarti, Mano Celestiale e l'alternanza dei sigilli con Torsione della Luce sono una tua scelta. Costruita da guide della beta di livello 30."
L["rm.mop.paladin.holy.Name"] = "Consigliata"
L["rm.mop.paladin.holy.Description"] = "Per Sacro, dal livello 10 nella specializzazione Sacro. Con un alleato come bersaglio cura: a 3 di potere sacro (o con Intento Divino) Luce dell'Alba quando tre persone vicino a te sono ferite, altrimenti Fiamma Eterna su un bersaglio che non l'ha, altrimenti Parola di Gloria; Folgore Sacra appena pronta; Infusione di Luce spesa in Splendore Sacro o Luce Divina, tre cumuli di Guaritore Altruista spesi in Splendore Sacro o Lampo di Luce; Lampo di Luce sotto il 35%; Splendore Sacro per un gruppo ferito; Luce Divina, poi Luce Sacra per completare. Con un nemico come bersaglio infligge danni: Folgore Sacra, Giudizio, Assalto del Crociato, Prisma Sacro, Sentenza d'Esecuzione, Martello dell'Ira, Biasimo. Promemoria: Sigillo dell'Intuito quando è attivo un altro sigillo (tranne Rettitudine) o nessuno, benedizioni, Predica, Faro di Luce e Scudo Sacro sul tuo focus (imposta il difensore come focus), Appello Divino sotto il 60% di mana, Martello della Luce e i tuoi tempi di recupero di cura quando tre persone sono sotto il 70%, Mano Celestiale su un bersaglio in punto di morte. La scelta di chi curare, le dissoluzioni e le cure al passaggio del mouse restano a te."
L["rm.mop.paladin.protection.Name"] = "Consigliata"
L["rm.mop.paladin.protection.Description"] = "Consigliata per Protezione, dal livello 10 nella specializzazione Protezione. Ingaggia con Scudo del Vendicatore, poi Scudo del Vendicatore con un proc di Gran Crociato, Scudo del Vendicatore, Martello dell'Ira, Assalto del Crociato, Giudizio, il tuo talento di livello 90, Consacrazione, Ira Sacra e Scudo Sacro. Con tre o più nemici addosso passa a Scudo del Vendicatore, Consacrazione, Martello del Virtuoso, Giudizio e Ira Sacra. Scudo del Virtuoso, Fiamma Eterna e Parola di Gloria sono fuori dal tempo di recupero globale, quindi si accendono accanto alla rotazione: Scudo del Virtuoso ogni volta che puoi permettertelo, Fiamma Eterna su di te quando sta per scadere con 3 di potere sacro e tre cumuli di Bastione della Gloria, Parola di Gloria sotto metà della salute senza quel talento. Altri promemoria: Giusta Furia, Sigillo dell'Intuito quando è attivo un altro sigillo (tranne Rettitudine) o nessuno, benedizioni, Predica, Scudo Sacro, Ira Vendicatrice e Vendicatore Sacro mentre fai da difensore, e Guardiano dei Re Antichi, Fervido Difensore, Protezione Divina e Mano Celestiale in base alla tua salute. Non può vedere i danni in arrivo, quindi pianifica tu le grandi abilità difensive."
L["rm.mop.paladin.protection.simulator.Name"] = "Accumulo di potere sacro (simulatore)"
L["rm.mop.paladin.protection.simulator.Description"] = "Un'alternativa alla rotazione integrata Protezione consigliata, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alzane la priorità. Segue le liste da difensore del simulatore: Scudo del Virtuoso aspetta il massimo di potere sacro a meno che tu non scenda sotto il 40% di salute o Intento Divino lo renda gratuito; Fiamma Eterna appena prima che svanisca con più di due cumuli di Bastione della Gloria; Scudo Sacro sempre attivo; Vendicatore Sacro e Ira Vendicatrice appena pronti. I generatori seguono Assalto del Crociato, Giudizio, poi Scudo del Vendicatore, Ira Sacra, il talento di livello 90 e Martello dell'Ira, con lo stesso ordine ad area contro tre nemici. Le abilità difensive sincronizzate con i boss spettano a te."
L["rm.mop.paladin.retribution.Name"] = "Consigliata"
L["rm.mop.paladin.retribution.Description"] = "Consigliata per Castigo, dal livello 10 nella specializzazione Castigo. Mantiene attiva Inquisizione (lanciata a 3 di potere sacro, rinnovata nei suoi ultimi 3 secondi; dal livello 81), spende Verdetto dei Templari al massimo di potere sacro o con un proc gratuito prima di generarne altro, poi Martello dell'Ira, Assalto del Crociato, Giudizio ed Esorcismo, e Verdetto dei Templari a 3 quando nient'altro è pronto. Durante Ira Vendicatrice spende subito e mette Giudizio prima di Assalto del Crociato. Con due o più nemici addosso passa a Tempesta Divina, con Martello del Virtuoso quando quattro sono vicini. Ingaggia dalla distanza con Giudizio o Esorcismo, e suggerisce Parola di Gloria quando sei da solo e in pericolo. Promemoria: Sigillo della Verità quando è attivo un altro sigillo o nessuno (Sigillo della Rettitudine viene mantenuto), Benedizione dei Re o del Vigore, Predica, Ira Vendicatrice e Guardiano dei Re Antichi con Inquisizione attiva sulle élite, Vendicatore Sacro durante Ira Vendicatrice, Sentenza d'Esecuzione e Martello della Luce, e Protezione Divina e Mano Celestiale quando sei in difficoltà. Sigillo della Rettitudine per i gruppi di nemici e la scelta dei glifi restano a te."
L["rm.mop.paladin.retribution.warcrafttavern.Name"] = "Prima Esorcismo (Warcraft Tavern)"
L["rm.mop.paladin.retribution.warcrafttavern.Description"] = "Un'alternativa alla rotazione integrata Castigo consigliata, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alzane la priorità. Esorcismo a ogni tempo di recupero e a ogni azzeramento di Arte della Guerra viene per primo; Inquisizione viene lanciata a qualsiasi livello di potere sacro quando manca e rinnovata a 3 nei suoi ultimi 20 secondi; poi Assalto del Crociato, Giudizio, Verdetto dei Templari e Martello dell'Ira (per primo durante Ira Vendicatrice con Ira Consacrata). Con due o più nemici usa Assalto del Crociato, Martello della Luce, Giudizio, Tempesta Divina e Martello dell'Ira. Ira Vendicatrice e Guardiano dei Re Antichi vengono suggeriti solo sulle élite. Il Sigillo della Rettitudine che la guida usa contro qualsiasi gruppo da colpire ad area è lasciato a te."
L["rm.mop.paladin.unspecialized.Name"] = "Prima di una specializzazione"
L["rm.mop.paladin.unspecialized.Description"] = "Per i livelli da 1 a 9, e qualsiasi paladino che non ha ancora scelto una specializzazione; la rotazione integrata di una specializzazione subentra appena ne scegli una. Ingaggia dalla distanza con Giudizio, poi Assalto del Crociato e Giudizio, con Martello della Giustizia quando sei da solo e sotto metà della salute e Parola di Gloria sotto il 40%. Promemoria: Sigillo del Comando (Sigillo della Verità dal 24) quando non lo hai attivo, Benedizione dei Re, Predica, e Lampo di Luce fuori dal combattimento quando sei ferito."
L["rm.retail.paladin.holy.Name"] = "Icy Veins"
L["rm.retail.paladin.holy.Description"] = "Sacro in Midnight, a titolo di riferimento: Rotation Master sceglie un incantesimo, non un bersaglio, e il gioco nasconde la salute di tutti in combattimento, quindi questa rotazione fa girare il tuo potere sacro e i tuoi tempi di recupero su qualunque bersaglio tu abbia e lascia a te la decisione su chi ha bisogno di cure. Il potere sacro resta visibile in combattimento, quindi viene speso prima a 5 e poi a 3 o più dopo le tue altre cure. Su un bersaglio amico: Fiamma Eterna o Parola di Gloria a 5 di potere sacro, Lampo di Luce con Infusione di Luce, Folgore Sacra, Fiamma Eterna o Parola di Gloria a 3 o più, Luce Sacra, Lampo di Luce; Luce dell'Alba resta a te. Su un nemico: Scudo del Virtuoso a 5 di potere sacro, Folgore Sacra, Scudo del Virtuoso a 3 o più, Giudizio, Assalto del Crociato, Consacrazione. Promemoria in combattimento: Rintocco Divino, Prisma Sacro, Baluardo Sacro o Arma Sacra, Faro di Virtù su un bersaglio amico, Protezione Divina; un'aura tra un ingaggio e l'altro; Predica. Mano Celestiale resta a te. Ira Vendicatrice e Maestria dell'Aura restano a te."
L["rm.retail.paladin.initial.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.paladin.initial.Description"] = "Consigliata prima di scegliere una specializzazione (mentre il gioco segnala la specializzazione iniziale del Paladino). Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, i promemoria che ogni rotazione integrata del Paladino condivide, ciascuno una volta che conosci il suo incantesimo. Quando scegli una specializzazione al livello 10, subentrano le rotazioni integrate di quella specializzazione."
L["rm.retail.paladin.protection.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.paladin.protection.Description"] = "Consigliata per Protezione in Midnight. Mostra il suggerimento dell'Assistente di Combattimento di Blizzard, che include già Scudo del Virtuoso, Ira Vendicatrice e Sentinella, e si ferma mentre lanci o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: un'aura tra un ingaggio e l'altro, Predica su un lancio interrompibile, e Fervido Difensore e Guardiano dei Re Antichi ogni volta che sono pronti in combattimento. La salute è nascosta su Retail, quindi decidi tu quando usarli, e Mano Celestiale. Le provocazioni e il posizionamento restano a te."
L["rm.retail.paladin.protection.icyveins.Name"] = "Riferimento (Icy Veins)"
L["rm.retail.paladin.protection.icyveins.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di Icy Veins e SimulationCraft richiede gli effetti benefici di Consacrazione, Avanguardia e Luce Brillante, che Midnight nasconde in combattimento. Consacrazione prima dell'ingaggio; poi Rintocco Divino, Martello della Luce, Consacrazione quando non ci sei sopra, Scudo del Vendicatore con Avanguardia, Scudo del Virtuoso a 3 o più di potere sacro, Martello dell'Ira, Giudizio, Martello Benedetto o Martello del Virtuoso, Scudo del Vendicatore, Parola di Gloria con Luce Brillante, Consacrazione. Promemoria: Ira Vendicatrice o Sentinella, Baluardo Sacro, Arma Sacra fuori da Ira Vendicatrice, abilità difensive, aura, Predica."
L["rm.retail.paladin.protection.wowhead.Name"] = "Consacrazione come riempitivo, riferimento (Wowhead)"
L["rm.retail.paladin.protection.wowhead.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine da difensore di Wowhead. Giudizio appena pronto, Scudo del Virtuoso, Scudo del Vendicatore, Rintocco Divino a 0 di potere sacro, Martello Benedetto o Martello del Virtuoso, e Consacrazione solo come riempitivo. La salute è nascosta su Retail, quindi Parola di Gloria sotto metà della salute spetta a te. Stessi promemoria del riferimento Icy Veins."
L["rm.retail.paladin.retribution.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.paladin.retribution.Description"] = "Consigliata per Castigo in Midnight. In combattimento il gioco ora nasconde agli addon effetti benefici, penalità, tempi di recupero e salute, quindi questa mostra il suggerimento stesso dell'Assistente di Combattimento di Blizzard (la rotazione a un pulsante) sulle tue barre delle azioni, e si ferma mentre lanci o quando non hai un nemico come bersaglio. Ti ricorda anche ciò che quel suggerimento non copre mai: un'aura tra un ingaggio e l'altro, Predica su un lancio interrompibile, e Protezione Divina ogni volta che è pronta in combattimento. La salute è nascosta su Retail, quindi decidi tu quando usare Protezione Divina e Mano Celestiale. I monili e le abilità razziali restano a te."
L["rm.retail.paladin.retribution.icyveins.Name"] = "Riferimento (Icy Veins)"
L["rm.retail.paladin.retribution.icyveins.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di Icy Veins e SimulationCraft legge effetti benefici, cariche e numero di nemici che Midnight nasconde in combattimento, quindi lì non può funzionare in modo affidabile. Martello della Luce; un'abilità di consumo gratuita con Intento Divino; a 5 di potere sacro mentre Scia di Ceneri è in tempo di recupero, l'abilità di consumo; Scia di Ceneri; Rintocco Divino; Lama della Giustizia con Arte della Guerra; Martello dell'Ira prima che raggiunga il massimo di cariche; a 3 o più di potere sacro, Tempesta Divina contro due o più nemici (o con Potenza Empirea), altrimenti Verdetto Finale; Martello dell'Ira; Lama della Giustizia; Giudizio; Assalto del Templare o Assalto del Crociato. Il potere sacro resta visibile in combattimento, quindi lì i punti in cui viene speso funzionano. Promemoria: Ira Vendicatrice, Sentenza d'Esecuzione con Scia di Ceneri pronta, aura, Predica, abilità difensive."
L["rm.sod.paladin.holy.Name"] = "Sacro (SoD)"
L["rm.sod.paladin.holy.Description"] = "Cure in gruppo della Season of Discovery, scelta con Faro di Luce, Luce Divina o Scudo Sacro incisi, o con l'albero Sacro senza Assalto del Crociato. Agisce sul tuo bersaglio amico: Purificazione, Folgore Sacra in movimento o sotto il 30%, Luce Divina (Luce Sacra quando il mana è sotto la metà) sotto il 60%, Lampo di Luce sotto il 90%. Con un nemico a portata di mischia si limita a mantenere attivo un sigillo. Promemoria: Faro di Luce e Scudo Sacro sul bersaglio che non li ha, Aura di Concentrazione o della Devozione, Benedizione della Saggezza, Favore Divino e Mano Celestiale per un bersaglio con pochissima salute. Le guide su cui si basa sono della Fase 4; la scelta di chi curare resta a te."
L["rm.sod.paladin.holy.wowhead.Name"] = "Sacro, prima Luce Sacra (SoD, Wowhead)"
L["rm.sod.paladin.holy.wowhead.Description"] = "L'ordine di cure della Fase 4 di Wowhead per un equipaggiamento ricco di critico, un'alternativa alla rotazione integrata consigliata Sacro della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Luce Divina o Luce Sacra sotto il 75%, poi Purificazione, Folgore Sacra per piccoli deficit o in movimento, Lampo di Luce sotto il 95%. Stessi promemoria della rotazione integrata consigliata."
L["rm.sod.paladin.protection.Name"] = "Protezione (SoD)"
L["rm.sod.paladin.protection.Description"] = "Ruolo da difensore della Season of Discovery, scelta con Giusta Furia, con Martello del Virtuoso o Scudo della Rettitudine incisi, o con l'albero Protezione. Sigillo del Martirio, un ingaggio con Scudo Benedetto, Scudo del Vendicatore ed Esorcismo, Scudo Benedetto sempre attivo; su un bersaglio Martello del Virtuoso, Scudo della Rettitudine, Esorcismo, Scudo del Vendicatore, Giudizio, Tempesta Divina, Consacrazione; con tre o più nemici addosso Martello del Virtuoso, Scudo del Vendicatore, Consacrazione, Scudo della Rettitudine, Esorcismo. Promemoria: Giusta Furia, Scudo Benedetto prima di un ingaggio, Aura della Devozione, Santuario o Re, Ira Vendicatrice, Protezione Divina sotto il 40%, Mano Celestiale, Imposizione della Sfida in gruppo quando il tuo bersaglio attacca qualcun altro."
L["rm.sod.paladin.protection.simulator.Name"] = "Protezione (SoD, simulatore)"
L["rm.sod.paladin.protection.simulator.Description"] = "La lista da difensore di simulatore, un'alternativa alla rotazione integrata consigliata Protezione della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Giudizio ogni volta che un sigillo è attivo, il sigillo rinnovato appena prima che scada, Scudo Benedetto, Scudo del Vendicatore, Martello del Virtuoso, Esorcismo, Scudo della Rettitudine per ultimo. Stessi promemoria della rotazione integrata consigliata."
L["rm.sod.paladin.retribution.Name"] = "Castigo (SoD)"
L["rm.sod.paladin.retribution.Description"] = "Mischia della Season of Discovery dal livello 1 al 60, e lì la scelta predefinita per qualsiasi Paladino. Mantiene attivo Sigillo del Martirio (Rettitudine finché non lo hai), apre con Esorcismo, lancia Tempesta Divina a tre di potere sacro, poi in base alla velocità dell'arma: con un'arma a due mani da 3,3 secondi o più lenta, Assalto del Crociato, Esorcismo, Tempesta Divina e Giudizio; con una più veloce, Giudizio solo quando il sigillo sta per scadere, poi Esorcismo, Assalto del Crociato e Tempesta Divina. Consacrazione con mana o contro tre nemici vicini, Ira Sacra su Non Morti e Demoni (su qualsiasi bersaglio con Potere Purificatore inciso), Martello dell'Ira con mana in avanzo (sempre con Martello dell'Ira Migliorato inciso). Le rune vengono usate man mano che le incidi. Promemoria: Aura della Santità, una Benedizione, Ira Vendicatrice con Maestria dell'Aura, una cura tra un combattimento e l'altro, Scudo Divino quando stai per morire."
L["rm.sod.paladin.retribution.icyveins.Name"] = "Castigo (SoD, Icy Veins Fase 4)"
L["rm.sod.paladin.retribution.icyveins.Description"] = "La vecchia lista della Fase 4 di Icy Veins e Warcraft Tavern, adatta anche al livellamento, un'alternativa alla rotazione integrata Castigo della Season of Discovery consigliata, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alzane la priorità. Giudizio del Crociato una volta sulle élite e nei combattimenti lunghi, Sigillo del Martirio, Esorcismo, Assalto del Crociato, Tempesta Divina e Giudizio appena pronti, Consacrazione con mana o contro tre nemici vicini, Martello dell'Ira. Stessi promemoria della rotazione consigliata."
L["rm.sod.paladin.retribution.stacking.Name"] = "Castigo, sigilli sovrapposti (SoD)"
L["rm.sod.paladin.retribution.stacking.Description"] = "Disattivata per impostazione predefinita; attivala con la runa Anima del Portasigilli o con il set da sei pezzi che fa persistere i sigilli (Rotation Master non può vedere né l'una né l'altro). Mantiene attivi sia Sigillo del Comando sia Sigillo del Martirio, Tempesta Divina a tre di potere sacro, Assalto del Crociato, Esorcismo, Ira Sacra su Non Morti e Demoni (su qualsiasi bersaglio con Potere Purificatore inciso), Consacrazione, e Giudizio mentre entrambi i sigilli sono attivi."
L["rm.sod.paladin.retribution.twist.Name"] = "Castigo, alternanza dei sigilli (SoD)"
L["rm.sod.paladin.retribution.twist.Description"] = "Disattivata per impostazione predefinita; attivala se alterni i sigilli con un'arma a due mani lenta. Passa tra Sigillo del Martirio e Sigillo del Comando negli ultimi 0,4 secondi prima di ogni colpo, non suggerisce nulla sul tempo di recupero globale negli 1,9 secondi che lo precedono, giudica mentre entrambi i sigilli persistono, e usa un riempitivo per colpo: Tempesta Divina a tre di potere sacro, Assalto del Crociato, Esorcismo. Richiede un timer degli attacchi e pratica."
L["rm.sod.paladin.shockadin.Name"] = "Shockadin (SoD, simulatore)"
L["rm.sod.paladin.shockadin.Description"] = "Disattivata per impostazione predefinita; attivala se infliggi danni con l'albero Sacro. Si applica con Sacro come albero principale e Shock and Awe inciso. Sigillo del Martirio (altrimenti Rettitudine), giudicato quando sta per scadere, Folgore Sacra per mantenere attiva Luce Solare o a tre di potere sacro, Esorcismo e Assalto del Crociato. Stessi promemoria della rotazione integrata Castigo della Season of Discovery."
L["rm.tbc.paladin.holy.Name"] = "Sacro (Icy Veins & Wowhead)"
L["rm.tbc.paladin.holy.Description"] = "Cure per un Paladino Sacro in gruppo, sul tuo bersaglio amico: Mano Celestiale o Folgore Sacra per un bersaglio in punto di morte, Purificazione (Purifica prima del 42), Folgore Sacra in movimento, Luce Sacra per danni pesanti, Luce Sacra di grado 5 per mantenere Grazia della Luce, altrimenti Lampo di Luce. Con un bersaglio ostile mantiene attivo Giudizio della Saggezza. Promemoria: Aura della Concentrazione, Benedizione della Saggezza, Illuminazione Divina e Favore Divino. Un Paladino Sacro che gioca da solo riceve invece una rotazione integrata Castigo."
L["rm.tbc.paladin.holy.wowhead.Name"] = "Sacro (cure sul difensore, Wowhead)"
L["rm.tbc.paladin.holy.wowhead.Description"] = "Le cure sul difensore in incursione di Wowhead, un'alternativa alla rotazione integrata consigliata Sacro, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Luce Sacra ogni volta che al tuo bersaglio manca un decimo della salute, Lampo di Luce solo per piccole carenze, con le stesse emergenze, purificazioni, Giudizio e promemoria della rotazione integrata Sacro combinata."
L["rm.tbc.paladin.protection.icyveins.Name"] = "Protezione (Icy Veins)"
L["rm.tbc.paladin.protection.icyveins.Description"] = "Il ruolo da difensore di Icy Veins, un'alternativa alla rotazione integrata consigliata Protezione di Wowhead, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Giudizio del Crociato quando nessuno lo mantiene, Rettitudine (Saggezza sui gruppi), Consacrazione come principale fonte di minaccia, Giudizio, Scudo Sacro, poi Scudo del Vendicatore e Martello dell'Ira appena pronti. Stessi promemoria della variante Wowhead, senza Ira Vendicatrice."
L["rm.tbc.paladin.protection.wowhead.Name"] = "Protezione (Wowhead & simulatore)"
L["rm.tbc.paladin.protection.wowhead.Description"] = "Ruolo da difensore per l'albero Protezione o per qualsiasi Paladino con Giusta Furia attiva. Ingaggia con Scudo Sacro, Scudo del Vendicatore e Giudizio; contro un bersaglio con colpi schiaccianti (boss mondiale o di tre o più livelli sopra di te) Scudo Sacro viene per primo; poi Consacrazione, Esorcismo su Non Morti e Demoni, Giudizio, Scudo Sacro, Biasimo sui gruppi di non morti, Scudo del Vendicatore tranne sui bersagli con colpi schiaccianti. Sigillo della Saggezza sui gruppi quando il mana è scarso, altrimenti Rettitudine. Promemoria: Giusta Furia, Aura della Devozione, Santuario (o Re, o Saggezza), Ira Vendicatrice, Mano Celestiale. Provocazioni e cambi di bersaglio restano a te."
L["rm.tbc.paladin.retribution.icyveins.Name"] = "Castigo (Icy Veins)"
L["rm.tbc.paladin.retribution.icyveins.Description"] = "Il Castigo di Icy Veins, un'alternativa alla rotazione integrata consigliata Castigo di Wowhead, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Giudizio del Crociato una volta per bersaglio, Sigillo della Rettitudine (Comando solo con un'arma lenta, Sangue o Martire una volta appresi), Assalto del Crociato, Martello dell'Ira e Giudizio appena pronti, Consacrazione contro due o più nemici, Esorcismo su Non Morti e Demoni, e Folgore Sacra per chi livella come Sacro. Stessi promemoria della variante Wowhead."
L["rm.tbc.paladin.retribution.twist.Name"] = "Castigo con alternanza dei sigilli"
L["rm.tbc.paladin.retribution.twist.Description"] = "Disattivata per impostazione predefinita; attivala se alterni i sigilli (livello 64+, Sigillo del Comando e Sangue o Martire). Apre con Giudizio del Crociato, poi a ogni colpo mette presto Sigillo del Comando (grado 1) e passa a Sangue o Martire negli ultimi 0,4 secondi, Assalto del Crociato tra un'alternanza e l'altra, giudica solo Sangue o Martire, Esorcismo e Consacrazione solo come riempitivi, e sotto il 12% di mana mantiene Sangue senza alternare. Richiede un timer degli attacchi affidabile; la latenza non viene considerata."
L["rm.tbc.paladin.retribution.wowhead.Name"] = "Castigo (Wowhead & simulatore)"
L["rm.tbc.paladin.retribution.wowhead.Description"] = "Castigo in mischia dal livello 1 al 70, e la scelta predefinita per qualsiasi Paladino a cui non si adatta nessun'altra rotazione integrata. Apre ogni bersaglio con Giudizio della Saggezza (mana basso) o del Crociato, mantiene attivo il tuo sigillo migliore (Sangue o Martire, Comando, poi Rettitudine), Assalto del Crociato, giudica solo Rettitudine, Sangue o Martire (o Comando su un bersaglio stordito), Esorcismo su Non Morti e Demoni, Consacrazione contro tre o più nemici se il mana lo consente. Martello dell'Ira è lasciato a te (Wowhead lo usa solo sui bersagli in fuga). Promemoria: Aura della Santità, del Castigo o della Devozione, una Benedizione su di te, una cura dopo il combattimento, Ira Vendicatrice. L'alternanza dei sigilli è una rotazione integrata separata."
